impl Deref for WebSocket {
    type Target = EventTarget;

    fn deref(&self) -> &EventTarget {
        // Never runs: rust-js compiles this `Deref` to the object itself.
        unsafe { &*(self as *const Self as *const EventTarget) }
    }
}

